/**
 * Prakriyā MCP server — Streamable HTTP, no auth, static data.
 *
 * All grammar data is precomputed JSON in ./public/data (generated by Vidyut
 * 0.4.0). This Worker is a read-only access layer: it never invents a form,
 * and every answer carries the sūtra steps the engine produced.
 *
 * Endpoint: POST /mcp   (GET /mcp -> 405)
 * Protocol: 2025-06-18, JSON responses (no SSE).
 */

const PROTOCOL = '2025-06-18';
const SERVER = { name: 'prakriya', version: '1.0.0' };

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Accept, MCP-Protocol-Version, Authorization',
  'Access-Control-Expose-Headers': 'MCP-Protocol-Version',
};

/* ---------------------------------------------------------------- data */
async function data(env, path) {
  const url = new URL(path, 'https://assets.local');
  const res = await env.ASSETS.fetch(new Request(url.toString()));
  if (!res.ok) throw new Error(`missing data ${path}`);
  return res.json();
}

let cache = {};
async function index(env) {
  if (!cache.index) cache.index = await data(env, '/data/index.json');
  return cache.index;
}
async function verbs(env) {
  if (!cache.verbs) cache.verbs = await data(env, '/data/verbs.json');
  return cache.verbs;
}
async function cases(env) {
  if (!cache.cases) cache.cases = await data(env, '/data/cases.json');
  return cache.cases;
}
async function family(env, id) {
  const key = `fam:${id}`;
  if (!cache[key]) {
    const ix = await index(env);
    const f = ix.families.find((x) => x.id === id);
    if (!f) throw new Error(`unknown family ${id}`);
    cache[key] = await data(env, '/' + f.file.replace(/^\/?/, ''));
  }
  return cache[key];
}

/* ---------------------------------------------------------------- helpers */
const norm = (s) => String(s || '').normalize('NFC').trim().replace(/\s+/g, ' ');
const low = (s) => norm(s).toLowerCase();
const bare = (s) => low(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();

const VIB_ALIAS = {
  prathama: ['prathama', 'nominative', 'nom'], dvitiya: ['dvitiya', 'accusative', 'acc', 'object'],
  tritiya: ['tritiya', 'instrumental', 'instr'], caturthi: ['caturthi', 'dative', 'dat'],
  pancami: ['pancami', 'ablative', 'abl'], sasthi: ['sasthi', 'genitive', 'gen'],
  saptami: ['saptami', 'locative', 'loc'], sambodhana: ['sambodhana', 'vocative', 'voc'],
};
const VAC_ALIAS = {
  eka: ['eka', 'ekavacana', 'singular', 'sg'], dvi: ['dvi', 'dvivacana', 'dual', 'du'],
  bahu: ['bahu', 'bahuvacana', 'plural', 'pl'],
};
const LAK_ALIAS = {
  lat: ['lat', 'present', 'pres'], lan: ['lan', 'past', 'imperfect', 'imperf'],
  lrt: ['lrt', 'future', 'fut'], lot: ['lot', 'imperative', 'imper'],
  vidhilin: ['vidhilin', 'optative', 'opt'],
};

function classify(text, table) {
  const t = ' ' + bare(text) + ' ';
  for (const [id, al] of Object.entries(table)) {
    if (al.some((a) => t.includes(' ' + a + ' '))) return id;
  }
  return null;
}

function vibOf(ix, v) { return ix.vibhakti.find((x) => x.id === v || x.en === low(v) || x.sanskrit === low(v)); }
function vacOf(ix, v) { return ix.vacana.find((x) => x.id === v || x.en === low(v) || x.sanskrit === low(v)); }

